API Gateway Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway Container") {
    Component(rate_limiting, "Rate Limiting Component", "Envoy WASM/Lua filter", "Enforces rate limits on incoming API requests to prevent abuse.")
    Component(geo_router, "Geo-Router Component", "Envoy routing filter", "Routes regional traffic to isolate workloads in appropriate data centers.")
    Component(auth_token, "Auth & Token Introspection Component", "Envoy OIDC/OAuth2 filter", "Validates security tokens and integrates with identity providers.")
    Component(upstream_proxy, "Upstream Proxy Component", "Envoy proxy cluster", "Proxies and balances traffic to upstream microservices.")
}

Rel(rate_limiting, upstream_proxy, "Inspects and passes allowed requests")
Rel(geo_router, upstream_proxy, "Directs traffic to regional endpoints")
Rel(auth_token, rate_limiting, "Authenticates requests before rate limiting")

@enduml

AI Symptom Checker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(ai_symptom_checker_container, "AI Symptom Checker Container") {
    Component(Symptom Router, "Symptom Router", "Python / FastAPI Router", "Handles incoming gRPC requests over mTLS and routes symptom triage payloads.")
    Component(Triage Engine, "Triage Engine", "Python / Asyncio", "Processes symptom inputs asynchronously for high-performance recommendation generation.")
    Component(Vertex AI Integration Client, "Vertex AI Integration Client", "Python / GCP SDK via Private Service Connect", "Communicates securely with GCP Vertex AI to fetch managed AI triage recommendations.")
}

Rel(Symptom Router, Triage Engine, "Forwards structured triage requests")
Rel(Triage Engine, Vertex AI Integration Client, "Invokes managed AI models")
@enduml

